Here is the root cause:
The bug was caused by the incorrect logic in the `ap_check_bindings_complete` function, which emitted the "AP bus change bindings complete" uevent every time an AP bus scan occurred, rather than only when all AP devices were bound to their respective drivers. Additionally, there was no mechanism to emit this event when an AP device switched drivers, leading to inconsistent event signaling regarding device bindings.

Here is the patch:
  */
 static void ap_check_bindings_complete(void)
 {
 	unsigned int apqns, bound;

 	if (atomic64_read(&ap_scan_bus_count) >= 1) {
 		ap_calc_bound_apqns(&apqns, &bound);
 		if (bound == apqns) {
 			if (!completion_done(&ap_apqn_bindings_complete)) {
 				complete_all(&ap_apqn_bindings_complete);
+				ap_send_bindings_complete_uevent();
 				pr_debug("%s all apqn bindings complete\n", __func__);
 			}
-			ap_send_bindings_complete_uevent();
 		}
 	}
 }


 static int ap_device_probe(struct device *dev)
 {
 	struct ap_device *ap_dev = to_ap_dev(dev);
 	struct ap_driver *ap_drv = to_ap_drv(dev->driver);
 	int card, queue, devres, drvres, rc = -ENODEV;

 	if (!get_device(dev))
 		return rc;

 	if (is_queue_dev(dev)) {
 		/*
 		 * If the apqn is marked as reserved/used by ap bus and
 		 * default drivers, only probe with drivers with the default
 		 * flag set. If it is not marked, only probe with drivers
 		 * with the default flag not set.
 		 */
 		card = AP_QID_CARD(to_ap_queue(dev)->qid);
 		queue = AP_QID_QUEUE(to_ap_queue(dev)->qid);
 		mutex_lock(&ap_perms_mutex);
 		devres = test_bit_inv(card, ap_perms.apm) &&
 			test_bit_inv(queue, ap_perms.aqm);
 		mutex_unlock(&ap_perms_mutex);
 		drvres = ap_drv->flags & AP_DRIVER_FLAG_DEFAULT;
 		if (!!devres != !!drvres)
 			goto out;
 	}

+	/*
+	 * Rearm the bindings complete completion to trigger
+	 * bindings complete when all devices are bound again
+	 */
+	reinit_completion(&ap_apqn_bindings_complete);
+
 	/* Add queue/card to list of active queues/cards */
 	spin_lock_bh(&ap_queues_lock);
 	if (is_queue_dev(dev))
 		hash_add(ap_queues, &to_ap_queue(dev)->hnode,
 			 to_ap_queue(dev)->qid);
 	spin_unlock_bh(&ap_queues_lock);

 	rc = ap_drv->probe ? ap_drv->probe(ap_dev) : -ENODEV;

 	if (rc) {
 		spin_lock_bh(&ap_queues_lock);
 		if (is_queue_dev(dev))
 			hash_del(&to_ap_queue(dev)->hnode);
 		spin_unlock_bh(&ap_queues_lock);
 	}

 out:
 	if (rc)
 		put_device(dev);
 	return rc;
 }



